const seedDir = path.resolve('modules/consulta-vet/data/seed');

let successCount = 0;

for (const [filename, compData] of Object.entries(complicationsMap)) {
  const filePath = path.join(seedDir, filename);
  if (!fs.existsSync(filePath)) {
    console.error(`File not found: ${filePath}`);
    continue;
  }

  let content = fs.readFileSync(filePath, 'utf8');

  // Check if complications already exists
  if (/^\s*complications:\s*\{/m.test(content)) {
    console.log(`[SKIP] ${filename} already has complications.`);
    continue;
  }

  // Find prevention
  const preventionRegex = /((\r?\n)([ \t]*)prevention:\s*\{?)/;
  const match = content.match(preventionRegex);
  if (!match) {
    console.error(`[ERROR] Could not find prevention in ${filename}`);
    continue;
  }

  const nl = match[2];
  const indent = match[3];

  // Format complications block
  const formatArray = (arr: string[]) => {
    return arr
      .map(item => `${indent}    ${JSON.stringify(item)},`)
      .join(nl);
  };

  const complicationsBlock = `${indent}complications: {${nl}` +
    `${indent}  principais: [${nl}` +
    `${formatArray(compData.principais)}${nl}` +
    `${indent}  ],${nl}` +
    `${indent}  prognostico:${nl}` +
    `${indent}    ${JSON.stringify(compData.prognostico)},${nl}` +
    `${indent}},${nl}${nl}`;

  // Insert complications right before prevention
  const replaced = content.replace(preventionRegex, `${complicationsBlock}$1`);
  fs.writeFileSync(filePath, replaced, 'utf8');
  console.log(`[SUCCESS] Added complications to ${filename}`);
  successCount++;
}

console.log(`\nFinished: successfully updated ${successCount} files.`);
